SELECT 'gongkao', '多人和差关系', 'kp-age-mp-sum-diff', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多人和差关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "大数 = (和 + 差) ÷ 2 ； 小数 = (和 - 差) ÷ 2。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "已知几个人年龄加起来是多少，谁比谁大多少。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是小学奥数最基础的“和差问题”，在行测中可以直接秒杀两人的具体年龄，无需列方程慢慢解。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 兄弟两人今年一共 30 岁，哥哥比弟弟大 4 岁。求哥哥几岁？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：典型的和差问题。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "套用大数公式：哥哥 = (30 + 4) ÷ 2 = 17 岁。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "套用小数公式：弟弟 = (30 - 4) ÷ 2 = 13 岁。"}]}]}]}]}$$ AS jsonb), NULL, '多人和差关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "多人和差关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_mp_sum_diff", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
